-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.require_admin_session()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not coalesce(public.token_session_open(), false) then
    raise exception 'session_closed' using errcode = '28000';
  end if;
  if not coalesce(public.is_admin(), false) then
    raise exception 'admin_only' using errcode = '42501';
  end if;
  return lower(trim(auth.jwt() ->> 'email'));
end;
$function$;

grant execute on function public.require_admin_session() to service_role;
